 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hi! Welcome to Nimbus Telecom. I'm Ravi. How can I help you today? 😊",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hey Ravi. I'm James Nair. I'm really fed up with the constant drops in my connection. It's unusable.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to hear that you're experiencing connection issues, James. I can certainly look into this for you. Could you please provide your account number and date of birth for verification?",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "Sure. Account number is 42809053 and my DOB is 09/09/1977.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. I've accessed your account. I see you're at 95 MG Road. Is that correct?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yeah, that's right. Look, I've had enough. I just want to cancel my service now.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to see you go. I can help you with that request. I'll go ahead and process the cancellation request for your account.",
      "tags": [
        "action:cancellation_or_retention"
      ]
    },
    {
      "speaker": "customer",
      "text": "Fine. Just make sure it's done. My phone is 94473 91878 and my email is james.49@examplemail.com if you need to send confirmation.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I've noted those details. However, I'm seeing a system error on my end that's preventing me from completing the cancellation right now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'll need to escalate this to my supervisor to get the account closed properly.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Are you kidding me?? I just want to leave and you can't even do a simple cancellation! This is ridiculous!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the frustration. Is there anything else I can assist you with today? I've escalated the request to the supervisor team, and they will handle the final steps. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
